suppressPackageStartupMessages({library(monocle);library(VGAM);library(Biobase);library(data.table);library(igraph)})
args <- commandArgs(trailingOnly=TRUE);base_dir<-normalizePath(if(length(args)) args[[1]] else ".",mustWork=TRUE)
input_dir<-file.path(base_dir,"data","ordering_input");table_dir<-file.path(base_dir,"refitted_trajectory");data_dir<-table_dir;dir.create(table_dir,recursive=TRUE,showWarnings=FALSE)
meta<-fread(file.path(input_dir,"P59_pooled_top100_cell_metadata.csv"),data.table=FALSE);features<-fread(file.path(input_dir,"P59_pooled_top100_selected_features.csv"),data.table=FALSE)
n_cells<-nrow(meta);n_features<-nrow(features);con<-file(file.path(input_dir,"P59_pooled_top100_selected_f64.bin"),"rb");vals<-readBin(con,"double",n=n_cells*n_features,size=8,endian="little");close(con)
expr<-matrix(vals,nrow=n_features,ncol=n_cells,byrow=TRUE);rownames(expr)<-features$feature_id;colnames(expr)<-meta$trajectory_cell_id;rownames(meta)<-meta$trajectory_cell_id;fd<-data.frame(gene_short_name=features$feature_id,row.names=features$feature_id,check.names=FALSE)
sigmas<-c(0.1);seeds<-c(20260918);out<-list();kout<-1
for(seed in seeds)for(sig in sigmas){tag<-paste0("sig",format(sig,scientific=FALSE),"_s",seed);message(tag)
 cds<-newCellDataSet(expr,phenoData=new("AnnotatedDataFrame",data=meta),featureData=new("AnnotatedDataFrame",data=fd),lowerDetectionLimit=-Inf,expressionFamily=VGAM::gaussianff());cds<-setOrderingFilter(cds,features$feature_id);set.seed(seed)
 cds<-reduceDimension(cds,max_components=2,reduction_method="DDRTree",norm_method="none",pseudo_expr=0,relative_expr=FALSE,auto_param_selection=FALSE,ncenter=50,sigma=sig,scaling=FALSE,verbose=FALSE);cds<-orderCells(cds)
 pd<-pData(cds);d0s<-table(pd$State[pd$day=="D0"]);alls<-table(pd$State);frac<-d0s/alls[names(d0s)];eligible<-d0s>=max(5,ceiling(sum(pd$day=="D0")*.05));cand<-names(d0s)[eligible];root<-as.numeric(cand[which.max(frac[cand])]);cds<-orderCells(cds,root_state=root);pd<-pData(cds);coords<-t(reducedDimS(cds));scaled<-numeric(nrow(pd));for(b in unique(pd$batch_short)){ix<-pd$batch_short==b;dn<-as.numeric(sub("D","",pd$day[ix]));scaled[ix]<-(dn-min(dn))/(max(dn)-min(dn))}
 g<-minSpanningTree(cds);rho<-suppressWarnings(cor(pd$Pseudotime,scaled,method="spearman"));out[[kout]]<-data.frame(sigma=sig,seed=seed,n_states=length(unique(pd$State)),branchpoints=sum(degree(g)>2),rho_scaled_day=rho,root_D0_fraction=unname(frac[as.character(root)]));kout<-kout+1
 if(seed==seeds[1]){tr<-pd;tr$cell_id<-rownames(tr);tr$DDRTree1<-coords[rownames(tr),1];tr$DDRTree2<-coords[rownames(tr),2];fwrite(tr[,c("cell_id","batch","batch_short","day","label","TIC","State","Pseudotime","DDRTree1","DDRTree2")],file.path(table_dir,paste0("P59_pooled_top100_nc50_",tag,"_trajectory_cells.csv")));ei<-as_edgelist(g,names=FALSE);kk<-reducedDimK(cds);nodes<-if(ncol(kk)==vcount(g))t(kk) else t(reducedDimS(cds));ed<-data.frame(x0=nodes[ei[,1],1],y0=nodes[ei[,1],2],x1=nodes[ei[,2],1],y1=nodes[ei[,2],2]);fwrite(ed,file.path(table_dir,paste0("P59_pooled_top100_nc50_",tag,"_trajectory_edges.csv")));saveRDS(cds,file.path(data_dir,paste0("P59_pooled_top100_nc50_",tag,"_cds.rds")),compress=FALSE)}
}
res<-rbindlist(out);fwrite(res,file.path(table_dir,"P59_pooled_top100_nc50_sigma_seed_stability.csv"));print(res)
